class BankAccount:
    def __init__(self, owner, balance=0): self.owner, self.balance = owner, balance
    def deposit(self, amount):
        if amount <= 0: raise ValueError('positive amount required')
        self.balance += amount
    def withdraw(self, amount):
        if amount <= 0 or amount > self.balance: raise ValueError('invalid withdrawal')
        self.balance -= amount

